css:
.print-format {
    padding: 15px !important;
}

body {
    color: #000;
    margin: 0;
}

body * {
    font-family: Calibri, Arial, sans-serif;
    font-size: 10px;
    line-height: 1.5em;
    box-sizing: border-box;
}

.logo-wrap {
    text-align: center;
    margin-bottom: 8px;
}

.logo {
    max-width: 90px;
    max-height: 60px;
}

.doc-title {
    font-size: 20px;
    font-weight: bold;
    padding: 8px 0 10px 6px;
}

table.outer {
    width: 100%;
    border: none;
    margin-bottom: 18px;
}

table.outer td {
    vertical-align: top;
    padding: 4px 8px;
}

.no-border,
.no-border td,
.no-border th {
    border: none !important;
}

.left-info,
.right-info {
    width: 50%;
}

.left-info div,
.right-info div {
    margin-bottom: 3px;
}

.data-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
}

.data-table th,
.data-table td {
    border: 0.4pt solid #dedede;
    padding: 6px !important;
    text-align: center;
}

.data-table th {
    background-color: #f5f5f5;
    font-weight: bold;
}

.text-left {
    text-align: left !important;
}

.items-table {
    margin-top: 8px;
}

.totals-row td {
    height: 28px;
}

.label-cell {
    font-weight: bold;
}

.summary-table {
    margin-top: 40px;
}

.terms {
    font-size: 12px;
    text-align: center;
    margin-top: 28px;
    padding-top: 10px;
    line-height: 1.8;
}

.footer {
    border-top: 0.4pt solid #dedede;
    font-size: 10px;
    text-align: center;
    margin-top: 50px;
    padding-top: 8px;
    line-height: 1.6;
}
/* One commercial line and its related services/accessories form one group. */
.items-table tbody.item-group { page-break-inside: avoid; break-inside: avoid; }
.items-table tbody.item-group > tr > td { border-top: none !important; border-bottom: none !important; }
.items-table tbody.item-group > tr:first-child > td { border-top: 0.4pt solid #dedede !important; }
.items-table .related-row td { padding-top: 3px !important; padding-bottom: 3px !important; }
.items-table .related-row td.text-left { padding-left: 14px !important; color: #555; }
.items-table .items-totals td { border-top: 0.4pt solid #dedede !important; }
.summary-table { margin-top: 22px; }
.summary-table th, .summary-table td { padding: 5px !important; }
.net-payable { font-weight: bold; }

/* Keep currency amounts together on one line. */
.items-table td:nth-last-child(-n+3), .summary-table td { white-space: nowrap; }

/* Strong frame and column borders; subtle horizontal article-group boundaries. */
.data-table { border: 0.75pt solid #777 !important; }
.data-table th, .data-table td { border-left: 0.75pt solid #777 !important; border-right: 0.75pt solid #777 !important; }
.data-table thead th { border-top: 0.75pt solid #777 !important; border-bottom: 0.75pt solid #777 !important; }
.items-table tbody.item-group > tr > td { border-top: none !important; border-bottom: none !important; }
.items-table tbody.item-group > tr:first-child > td { border-top: 0.4pt solid #dedede !important; }
.items-table .items-totals td { border-top: 0.75pt solid #777 !important; }
.summary-table td { border-top: 0.75pt solid #777 !important; border-bottom: 0.75pt solid #777 !important; }

/* The Desk/PDF print wrapper provides the page padding, as in Quotation. */
.devis-v2-content { width: 100%; margin: 0; padding: 0; }

.section-heading td {text-align:left!important;background:#e9eef2;font-weight:bold;padding:7px!important;}
.work-type-heading td {text-align:left!important;background:#f5f7f9;font-weight:bold;padding:6px!important;}

html:
{% macro amount_display(value, currency, precision=2) -%}
{{ frappe.utils.fmt_money(value, precision=precision, currency=currency, format='#,###') if currency not in ('XOF','XAF') else frappe.utils.fmt_money(value, precision=0, format='#,###') }}
{%- endmacro %}
<div class="devis-v2-content">

    <div class="logo-wrap">
        <img src="/files/DAL ALU Logo.jpg" class="logo">
    </div>

    <div class="doc-title">DEVIS</div>

    <table class="outer no-border info-table">
        <tr>
            <td class="left-info">
                <div><b>N° Proforma :</b> {{ doc.name or "" }}</div>
                <div><b>Référence :</b> {{ doc.get("custom_reference") or "" }}</div>
                <div><b>Date :</b> {{ frappe.utils.formatdate(doc.get("transaction_date")) if doc.get("transaction_date") else "" }}</div>
            </td>
            <td class="right-info">
                <div><b>Client :</b> {{ doc.get("customer_name") or doc.get("party_name") or doc.get("customer") or "" }}</div>
                <div><b>Téléphone :</b> {{ doc.get("custom_phone_number") or "" }}</div>
                <div><b>Adresse :</b> {{ doc.get("address_display") or "" }}</div>
                <div><b>N° CC :</b> {{ doc.get("custom_n_cc") or "" }}</div>
            </td>
        </tr>
    </table>

    {% set ns = namespace(total_surface=0, total_ml=0, total_discount=0, airsi=0) %}
    {% set item_names = doc.items | map(attribute='name') | list %}
    {% macro item_row(item, related=false) %}
        {% set extra = related or item.get('custom_is_service_row') or item.get('custom_is_accessory_row') %}
        {% set l = 0 if extra else (item.get('custom_client_length_mm') or 0) | float %}
        {% set h = 0 if extra else (item.get('custom_client_width_mm') or 0) | float %}
        {% set qty = (item.get('qty') or 0) | float %}
        {% set m2 = l * h / 1000000 %}
        {% set ml = 2 * (l + h) / 1000 %}
        {% set rem = (item.get('discount_amount') or 0) | float %}
        {% set ns.total_surface = ns.total_surface + m2 * qty %}
        {% set ns.total_ml = ns.total_ml + ml * qty %}
        {% set ns.total_discount = ns.total_discount + rem * qty %}
        <tr class="{{ 'related-row' if related else 'parent-row' }}" data-row-name="{{ item.name }}" data-parent-row="{{ item.get('custom_parent_row') or '' }}">
            <td>{{ (item.get('custom_repere') if item.get('custom_ug_work_type') else item.get('item_code')) or '' }}</td>
            <td class="text-left">{{ item.get('description') or item.get('item_name') or '' }}</td>
            <td>{{ '{:g}'.format(qty) }}</td>
            <td>{{ '{:,.0f}'.format(l).replace(',', ' ') if l else '' }}</td>
            <td>{{ '{:,.0f}'.format(h).replace(',', ' ') if h else '' }}</td>
            <td>{{ '{:,.4f}'.format(m2).replace(',', ' ') if l and h else '' }}</td>
            <td>{{ '{:,.2f}'.format(ml).replace(',', ' ') if l and h else '' }}</td>
            <td>{{ amount_display(item.get('custom_ug_pricing_rate') if item.get('custom_ug_price_per_sqm') else (item.get('rate') or 0), currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}{% if item.get('custom_ug_price_per_sqm') %} / m²{% endif %}</td>
            <td>{{ amount_display((item.get('custom_ug_pricing_rate') or 0) * (item.get('discount_percentage') or 0) / 100 if item.get('custom_ug_price_per_sqm') else rem, currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}</td>
            <td>{{ amount_display(item.get('amount') or 0, currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}</td>
        </tr>
    {% endmacro %}
    <table class="data-table items-table">
        <thead><tr><th>Référence</th><th>Désignation</th><th>Qté</th><th>L</th><th>H</th><th>M²</th><th>M.L.</th><th>P.U.</th><th>Rem.</th><th>Montant HT</th></tr></thead>
        {% set grouping = namespace(section=none, work_type=none) %}
        {% for parent in doc.items if not parent.get('custom_parent_row') or parent.get('custom_parent_row') not in item_names %}
        {% if parent.get('custom_ug_work_type') %}
            {% if parent.get('custom_chantier_section') != grouping.section %}
                {% set grouping.section = parent.get('custom_chantier_section') %}
                {% set grouping.work_type = none %}
                <tbody class="section-heading"><tr><td colspan="10">{{ (frappe.db.get_value('Chantier Section', grouping.section, 'section_name') if grouping.section else 'Sans section') | e }}</td></tr></tbody>
            {% endif %}
            {% if parent.custom_ug_work_type != grouping.work_type %}
                {% set grouping.work_type = parent.custom_ug_work_type %}
                <tbody class="work-type-heading"><tr><td colspan="10">{{ parent.get('custom_ug_work_type_name') | e }} — {{ parent.get('custom_client_thickness_mm') | int }} mm</td></tr></tbody>
            {% endif %}
        {% endif %}
        <tbody class="item-group">
            {{ item_row(parent) }}
            {% for extra in doc.items if extra.get('custom_parent_row') == parent.name %}
                {{ item_row(extra, true) }}
            {% endfor %}
        </tbody>
        {% endfor %}
        <tbody class="items-totals"><tr class="totals-row">
            <td colspan="5" class="label-cell text-left">TOTAL</td>
            <td>{{ '{:,.4f}'.format(ns.total_surface).replace(',', ' ') }}</td>
            <td>{{ '{:,.2f}'.format(ns.total_ml).replace(',', ' ') }}</td>
            <td></td>
            <td>{{ amount_display(ns.total_discount, currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}</td>
            <td>{{ amount_display(doc.get('total') or 0, currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}</td>
        </tr></tbody>
    </table>

    {% for tax in doc.get('taxes', []) %}
        {% set identity = ((tax.get('description') or '') ~ ' ' ~ (tax.get('account_head') or '')) | upper %}
        {% if 'AIRSI' in identity %}
            {% set value = tax.get('tax_amount_after_discount_amount') if tax.get('tax_amount_after_discount_amount') is not none else (tax.get('tax_amount') or 0) %}
            {% set ns.airsi = ns.airsi + value %}
        {% endif %}
    {% endfor %}
    <table class="data-table summary-table">
        <thead><tr>
            <th>TOTAL HT</th><th>REMISE COMPL.</th><th>TOTAL HT NET</th>
            {% for tax in doc.get('taxes', []) %}
                {% set identity = ((tax.get('description') or '') ~ ' ' ~ (tax.get('account_head') or '')) | upper %}
                {% if 'AIRSI' not in identity %}
                    <th>{% if 'TVA' in identity or 'VAT' in identity or ((tax.get('description') or '') | trim | upper in ['METRIC', 'METRIC @ 18.0'] and 'VAT' in (doc.get('taxes_and_charges') or '') | upper) %}TVA{% else %}{{ tax.get('description') or tax.get('account_head') or 'Taxe' }}{% endif %}{% if tax.get('charge_type') != 'Actual' %} {{ '{:g}'.format(tax.get('rate') or 0) }} %{% endif %}</th>
                {% endif %}
            {% endfor %}
            {% for tax in doc.get('taxes', []) %}
                {% set identity = ((tax.get('description') or '') ~ ' ' ~ (tax.get('account_head') or '')) | upper %}
                {% set value = tax.get('tax_amount_after_discount_amount') if tax.get('tax_amount_after_discount_amount') is not none else (tax.get('tax_amount') or 0) %}
                {% if 'AIRSI' in identity and value | float != 0 %}<th>AIRSI{% if tax.get('charge_type') != 'Actual' %} {{ '{:g}'.format(tax.get('rate') or 0) }} %{% endif %}</th>{% endif %}
            {% endfor %}
            <th>TOTAL TTC</th>

            <th>NET À PAYER</th>
        </tr></thead>
        <tbody><tr>
            <td>{{ amount_display(doc.get('total') or 0, currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}</td>
            <td>{{ amount_display(doc.get('discount_amount') or 0, currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}</td>
            <td>{{ amount_display(doc.get('net_total') or 0, currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}</td>
            {% for tax in doc.get('taxes', []) %}
                {% set identity = ((tax.get('description') or '') ~ ' ' ~ (tax.get('account_head') or '')) | upper %}
                {% if 'AIRSI' not in identity %}
                    {% set value = tax.get('tax_amount_after_discount_amount') if tax.get('tax_amount_after_discount_amount') is not none else (tax.get('tax_amount') or 0) %}
                    <td>{{ amount_display(value, currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}</td>
                {% endif %}
            {% endfor %}
            {% for tax in doc.get('taxes', []) %}
                {% set identity = ((tax.get('description') or '') ~ ' ' ~ (tax.get('account_head') or '')) | upper %}
                {% set value = tax.get('tax_amount_after_discount_amount') if tax.get('tax_amount_after_discount_amount') is not none else (tax.get('tax_amount') or 0) %}
                {% if 'AIRSI' in identity and value | float != 0 %}
                    <td>{{ amount_display(value, currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}</td>
                {% endif %}
            {% endfor %}
            <td>{{ amount_display((doc.get('grand_total') or 0) - ns.airsi, currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}</td>

            <td class="net-payable">{{ amount_display(doc.get('rounded_total') if not doc.get('disable_rounded_total') and doc.get('rounded_total') else (doc.get('grand_total') or 0), currency=doc.currency, precision=0 if doc.currency in ('XOF', 'XAF') else 2) }}</td>
        </tr></tbody>
    </table>

    <div class="terms">
        <div>Les articles vendus ne sont ni repris ni échangés.</div>
        <div>
            Arrêté le présent devis à la somme de :
            {{ doc.get("in_words") or "" }}
        </div>
    </div>

    <div class="footer">
        DAL-ALU KINSHASA SARL<br>
        N° Impôt A2409344Y - ID Nat 05-H5300-N43768E - RCCM CD/KIN/RCCM/24-B-06887<br>
        20, Avenue Colonel Mondjiba, Kinshasa Ngaliema - RDC<br>
        Téléphone : 0999781511 / 0813334291<br>
        Email : dalalurdc@gmail.com
    </div>

</div>

css:
.print-format {padding:15px!important;}
.production-sheet {font-family:Arial,sans-serif;color:#111;font-size:12px;line-height:1.45;}
.production-sheet * {box-sizing:border-box;}
.production-sheet h1 {font-size:22px;font-weight:bold;margin:8px 0 20px;}
.production-sheet .outer {width:100%;border:0;margin-bottom:16px;}
.production-sheet .outer td {border:0;padding:4px 8px;vertical-align:top;width:50%;}
.production-sheet .logo td {text-align:center;width:100%;}
.production-sheet .logo img {max-height:100px;max-width:150px;}
.production-sheet .description {margin:8px 0;}
.production-sheet .data-table {width:100%;table-layout:fixed;border-collapse:collapse;margin-top:16px;}
.production-sheet .data-table th,.production-sheet .data-table td {border:1px solid #555;padding:6px 3px;text-align:center;vertical-align:top;font-size:10px;line-height:1.4;}
.production-sheet .data-table th {background:#f3f3f3;font-weight:bold;font-size:9px;vertical-align:middle;}
.production-sheet .data-table th small {font-size:9px;font-weight:normal;}
.production-sheet .data-table .designation {text-align:left;padding:7px 6px;overflow-wrap:anywhere;}
.production-sheet .designation strong {font-size:10.5px;}
.production-sheet .detail {color:#555;font-size:9px;margin-top:3px;}
.production-sheet .associated {font-size:9px;margin-top:4px;}
.production-sheet .numeric,.production-sheet .operation-value {white-space:nowrap;}
.production-sheet .operation-value + .operation-value {margin-top:3px;}
.production-sheet .absent {color:#777;}
.production-sheet tfoot td {font-weight:bold;background:#f6f6f6;}
.production-sheet .data-table .total-unit {text-align:left;}
.production-sheet thead {display:table-header-group;}
.production-sheet tfoot {display:table-row-group;}
.production-sheet tr {page-break-inside:avoid;}
.production-sheet .legend {font-size:9px;margin-top:8px;color:#555;}
.production-sheet .terms {font-size:11px;text-align:center;margin-top:28px;}
.production-sheet .footer {border-top:1px solid #555;font-size:9px;text-align:center;margin-top:32px;padding-top:8px;}

.print-format .production-sheet .data-table th {font-size:9px!important;padding:6px 2px!important;white-space:normal;overflow-wrap:anywhere;}
.print-format .production-sheet .data-table td {font-size:10px!important;padding:6px 3px!important;}

html:
{% macro number(value, precision=2) -%}{{ ('%.*f' % (precision, (value or 0)|float)).rstrip('0').rstrip('.') if precision else '%d' % ((value or 0)|float) }}{%- endmacro %}
{% macro unit(row) -%}{% set u = row.get('uom') or row.get('stock_uom') or '' %}{{ 'm' if u in ['Meter', 'Mètre'] else 'u' if u in ['Nos', 'PC', 'Unit'] else 'm²' if u == 'Square Meter' else u }}{%- endmacro %}
{% macro operation(row) -%}
{% if not row.get('custom_is_accessory_row') and (row.get('custom_is_service_row') or row.get('custom_item_type') == 'SERVICE') %}
{% set label = ((row.get('item_name') or '') ~ ' ' ~ (row.get('description') or '')|striptags)|upper|replace('É','E')|replace('È','E') %}
{% if 'RABOT' in label %}rabotage{% elif 'TROU' in label or 'PERCAGE' in label %}trous{% elif 'ENCOCH' in label %}encoche{% elif 'BISOT' in label or 'BISEAU' in label %}biseautage{% elif 'SABL' in label %}sablage{% elif 'TREMP' in label %}trempe{% endif %}
{% endif %}
{%- endmacro %}
{% macro operation_cell(parent, key) -%}
{% set ns=namespace(found=false) %}
{% for service in doc.items %}{% if service.get('custom_parent_row') == parent.name and operation(service)|trim == key %}
{% set ns.found=true %}<div class="operation-value">{{ number(service.qty) }} {{ unit(service) }}</div>
{% endif %}{% endfor %}{% if not ns.found %}<span class="absent">—</span>{% endif %}
{%- endmacro %}
{% set row_names=doc.items|map(attribute='name')|list %}
<div class="production-sheet">
<table class="outer logo"><tr><td><img src="https://fimaci.frappe.cloud/files/UG.jpeg" alt="Univers Glass"></td></tr></table>
<h1>Fiche de production</h1>
<table class="outer information"><tr><td>
<div><strong>N° Proforma :</strong> {% if doc.get('custom_quotation') %}{{ doc.custom_quotation }}{% else %}{% set refs=namespace(values=[]) %}{% for row in doc.items %}{% if row.get('prevdoc_docname') and row.prevdoc_docname not in refs.values %}{% set refs.values=refs.values+[row.prevdoc_docname] %}{% endif %}{% endfor %}{{ refs.values|join(', ') or '—' }}{% endif %}</div>
<div><strong>Commande client :</strong> {{ doc.name }}</div>
<div><strong>Référence :</strong> {{ doc.get('custom_reference') or doc.get('reference') or doc.get('custom_chantier') or doc.get('po_no') or '—' }}</div>
</td><td><div><strong>Client :</strong> {{ doc.get('customer_name') or doc.customer }}</div>
<div><strong>Date :</strong> {{ doc.get_formatted('transaction_date') }}</div>
{% if doc.get('delivery_date') %}<div><strong>Livraison prévue :</strong> {{ doc.get_formatted('delivery_date') }}</div>{% endif %}
</td></tr></table>
{% if doc.get('custom_description') %}<div class="description">{{ doc.custom_description }}</div>{% endif %}
<table class="data-table"><colgroup><col style="width:30%"><col style="width:5%"><col style="width:7%"><col style="width:7%"><col style="width:8%">{% for i in range(6) %}<col style="width:7.1666%">{% endfor %}</colgroup>
<thead><tr><th>Désignation / repère</th><th>Qté</th><th>L<br><small>mm</small></th><th>H<br><small>mm</small></th><th>m²/u</th><th>Rabotage</th><th>Trous</th><th>Encoche</th><th>Biseautage</th><th>Sablage</th><th>Trempe</th></tr></thead>
<tbody>{% set totals=namespace(qty=0,area=0) %}
{% for row in doc.items %}
{% if not row.get('custom_parent_row') or row.custom_parent_row not in row_names %}
{% set extra=row.get('custom_is_service_row') or row.get('custom_is_accessory_row') %}
{% set l=(row.get('custom_client_length_mm') or 0)|float %}{% set h=(row.get('custom_client_width_mm') or 0)|float %}
{% set area=l*h/1000000 %}
{% if not extra %}{% set totals.qty=totals.qty+row.qty %}{% set totals.area=totals.area+area*row.qty %}{% endif %}
<tr data-row="{{ row.name }}"><td class="designation"><strong>{{ row.get('item_name') or row.item_code }}</strong>
<div class="detail">{{ row.get('custom_repere') or row.item_code }}{% if row.get('custom_client_thickness_mm') %} · Ép. {{ number(row.custom_client_thickness_mm) }} mm{% endif %}</div>
{% if extra %}<div class="detail">{{ 'Accessoire' if row.get('custom_is_accessory_row') else 'Service' }} non affecté à un ouvrage · {{ number(row.qty) }} {{ unit(row) }}</div>{% endif %}
{% for child in doc.items %}{% if child.get('custom_parent_row') == row.name %}
<div class="associated">{{ 'Accessoire' if child.get('custom_is_accessory_row') else 'Service' }} : {{ child.get('item_name') or child.item_code }} — {{ number(child.qty) }} {{ unit(child) }}</div>
{% endif %}{% endfor %}
</td><td class="numeric">{{ number(row.qty) }}{% if extra %}<br>{{ unit(row) }}{% endif %}</td><td class="numeric">{{ number(l) if l else '—' }}</td><td class="numeric">{{ number(h) if h else '—' }}</td><td class="numeric">{{ number(area,4) if area else '—' }}</td>
{% for key in ['rabotage','trous','encoche','biseautage','sablage','trempe'] %}<td>{{ operation_cell(row,key) }}</td>{% endfor %}</tr>
{% endif %}{% endfor %}</tbody>
<tfoot><tr><td class="designation">Total ouvrages</td><td>{{ number(totals.qty) }}</td><td colspan="2">Surface totale</td><td class="numeric">{{ number(totals.area,4) }}</td><td colspan="6" class="total-unit">m²</td></tr></tfoot></table>
<div class="legend">L et H : dimensions d’une pièce en mm. m²/u : surface d’une pièce. Opérations : quantités totales commandées pour la ligne, dans l’unité indiquée. — : aucune opération associée.</div>
<div class="terms">Les articles vendus ne sont ni repris ni échangés.</div>
<div class="footer">Abidjan Yopougon Zone Industrielle entre le GS les Saints Anges et Airplast - 01 BP 1107 Abidjan 01,<br>Tél: (225) 27 23 50 61 02 - Fax: (225) 27 23 50 61 02<br>R.C. N°: CI-YOP-2008-B-312 - ECOBANK N°: CI 059010011210773180154,<br>E-mail: univers.glass@hotmail.fr</div>
</div>

