{% if doc.custom_ug_order_type == 'B' %}
<h1>Sortie directe B</h1>
<p><strong>Commande B :</strong> {{ (doc.name) | e }}<br><strong>Client :</strong> {{ (doc.customer_name or doc.customer) | e }}<br><strong>Date de commande :</strong> {{ frappe.utils.formatdate(doc.transaction_date) }}</p>
{% set movements=frappe.get_all('Stock Entry',filters={'custom_ug_b_sales_order':doc.name,'docstatus':1},fields=['name','posting_date'],order_by='posting_date,name') %}
{% if not movements %}<p>Aucune sortie physique validée pour cette commande.</p>{% endif %}
{% for movement in movements %}
<h3>Sortie {{ (movement.name) | e }} — {{ frappe.utils.formatdate(movement.posting_date) }}</h3>
<table><thead><tr><th>Désignation</th><th>Qté</th><th>Unité</th><th>L × H (mm)</th><th>N° de série / lot</th></tr></thead><tbody>
{% set stock=frappe.get_doc('Stock Entry',movement.name) %}
{% for row in stock.items %}
<tr><td>{{ (frappe.db.get_value('Sales Order Item', {'name': row.custom_sales_order_item, 'parent': doc.name}, 'item_name') or row.item_name or row.item_code) | e }}</td><td>{{ '%g' % row.qty }}</td><td>{{ (row.uom) | e }}</td><td>{% if row.custom_dimension_length_mm and row.custom_dimension_width_mm %}{{ '%g' % row.custom_dimension_length_mm }} × {{ '%g' % row.custom_dimension_width_mm }}{% endif %}</td><td>
{% if row.serial_and_batch_bundle %}{% for serial in frappe.get_all('Serial and Batch Entry',filters={'parent':row.serial_and_batch_bundle},fields=['serial_no','batch_no'],order_by='idx') %}{{ (serial.serial_no or serial.batch_no or '') | e }}<br>{% endfor %}{% else %}<span style="white-space:pre-line">{{ (row.serial_no or row.batch_no or '') | e }}</span>{% endif %}
</td></tr>{% endfor %}</tbody></table>{% endfor %}
<div class="signatures"><p>Remis par : ____________________</p><p>Reçu par : ____________________</p><p>Date : ____________________</p></div>
{% else %}<p>Ce bon est réservé aux commandes B.</p>{% endif %}
